def _dump(node):
    return ast.dump(node, include_attributes=False)


def _code_shape(code):
    return tuple(getattr(code, name) for name in (
        'co_code', 'co_names', 'co_varnames', 'co_argcount', 'co_posonlyargcount',
        'co_kwonlyargcount', 'co_flags', 'co_freevars', 'co_cellvars')) + (tuple(
            _code_shape(value) if type(value) is CodeType else value
            for value in code.co_consts),)


def _top_code(code, name):
    found = [value for value in code.co_consts if type(value) is CodeType
        and value.co_name == name and value.co_qualname == name]
    if len(found) != 1:
        raise ValueError('one complete top-level city-scene owner required: ' + name)
    return found[0]


def _cooperative_module(group, original_tree):
    """Exact whole FN and actual whole module inverse, not a shape allowance."""
    names = (LOWBANK_VIEWS if group == 'lowbank' else
        {'bootstrap_main_program': {'_bootstrap_dispatch_call_steps': 1}})
    if group not in ('lowbank', 'bootstrap'):
        raise ValueError('only the finite Lowbank/main source modules are lifted')
    result = copy.deepcopy(original_tree)
    inverses = {}
    admissions = []
    for index, original in enumerate(original_tree.body):
        if not isinstance(original, ast.FunctionDef) or original.name not in names:
            continue
        expected = ast.parse(EXPECTED_WHOLE_SOURCES[group][original.name]).body
        if len(expected) != 1 or _dump(original) != _dump(expected[0]) or index in inverses:
            raise ValueError('complete reviewed city-scene source differs: ' + original.name)
        spec = names[original.name]
        counts = {name: 0 for name in spec}
        changes = []

        class Lift(ast.NodeTransformer):
            def visit_Call(self, node):
                node = self.generic_visit(node)
                if not isinstance(node.func, ast.Name) or node.func.id not in spec:
                    return node
                before = copy.deepcopy(node)
                name = node.func.id
                counts[name] += 1
                if group == 'bootstrap':
                    # Already inside the original yield-from; change its sole
                    # private binding, not the surrounding complete main body.
                    node.func.id = '_city_scene_main_dispatch'
                    after = copy.deepcopy(node)
                elif original.name == '_lowbank_ui_call_fields':
                    node.func.id = '_city_scene_lowbank_child'
                    node.args.append(ast.Name(id='continuation', ctx=ast.Load()))
                    after = ast.copy_location(ast.YieldFrom(value=node), node)
                else:
                    after = ast.copy_location(ast.YieldFrom(value=node), node)
                changes.append((before, copy.deepcopy(after)))
                return after

        derived = Lift().visit(copy.deepcopy(original))
        if counts != spec:
            raise ValueError('exact city-scene propagation count differs: ' + original.name)
        remaining = list(changes)

        class Inverse(ast.NodeTransformer):
            def visit_YieldFrom(self, node):
                if group == 'bootstrap':
                    return self.generic_visit(node)
                for position, (before, after) in enumerate(remaining):
                    if _dump(node) == _dump(after):
                        remaining.pop(position)
                        return ast.copy_location(copy.deepcopy(before), node)
                raise ValueError('non-admitted city-scene yield-from')

            def visit_Call(self, node):
                if group == 'bootstrap':
                    for position, (before, after) in enumerate(remaining):
                        if _dump(node) == _dump(after):
                            remaining.pop(position)
                            return ast.copy_location(copy.deepcopy(before), node)
                return self.generic_visit(node)

        inverse = Inverse().visit(copy.deepcopy(derived))
        if remaining or _dump(inverse) != _dump(original):
            raise ValueError('complete city-scene FN inverse differs: ' + original.name)
        result.body[index] = derived
        inverses[index] = inverse
        admissions.append((original.name, counts))
    if len(inverses) != len(names):
        raise ValueError('every finite city-scene whole owner required')
    restored = copy.deepcopy(result)
    for index, inverse in inverses.items():
        restored.body[index] = inverse
    if _dump(restored) != _dump(original_tree):
        raise ValueError('complete city-scene module inverse differs')
    return ast.fix_missing_locations(result), admissions


def _prepare_city_artifacts(module, group, source, filename):
    original_tree = ast.parse(source, filename=filename)
    plain = compile(original_tree, filename, 'exec', dont_inherit=True)
    for name, expected_source in EXPECTED_WHOLE_SOURCES[group].items():
        original = getattr(module, name)
        nodes = [node for node in original_tree.body
            if isinstance(node, ast.FunctionDef) and node.name == name]
        if (len(nodes) != 1 or _dump(nodes[0]) != _dump(ast.parse(expected_source).body[0])
                or type(original) is not FunctionType or original.__globals__ is not vars(module)
                or original.__module__ != module.__name__ or original.__name__ != name
                or original.__closure__ is not None
                or _code_shape(_top_code(plain, name)) != _code_shape(original.__code__)):
            raise ValueError('actual complete city-scene owner required: ' + name)
    derived_tree, admissions = _cooperative_module(group, original_tree)
    derived = compile(derived_tree, filename, 'exec', dont_inherit=True)
    return dict(plain=plain, derived=derived, admissions=admissions)


def _compile_views(module, group):
    filename, source = read_source_text(module)
    artifacts = get_source_artifacts('city', module.__name__, group,
        source_text=source, filename=filename,
        transformer_codes=(_prepare_city_artifacts.__code__, _cooperative_module.__code__,
            _dump.__code__, _code_shape.__code__, _top_code.__code__, _compile_views.__code__),
        expected_contract=dict(expected=EXPECTED_WHOLE_SOURCES[group], views=LOWBANK_VIEWS),
        prepare=lambda: _prepare_city_artifacts(module, group, source, filename))
    plain, derived = artifacts['plain'], artifacts['derived']
    originals = {}
    for name in EXPECTED_WHOLE_SOURCES[group]:
        original = getattr(module, name)
        if (type(original) is not FunctionType or original.__globals__ is not vars(module)
                or original.__module__ != module.__name__ or original.__name__ != name
                or original.__closure__ is not None
                or _code_shape(_top_code(plain, name)) != _code_shape(original.__code__)):
            raise ValueError('actual complete city-scene owner required: ' + name)
        originals[name] = original
    namespace = dict(vars(module))
    for name in ('_city_scene_lowbank_child', '_city_scene_main_dispatch'):
        if name in namespace:
            raise ValueError('private city-scene name must not shadow business binding')
    names = LOWBANK_VIEWS if group == 'lowbank' else ('bootstrap_main_program',)
    views = {}
    for name in names:
        original = originals[name]
        view = FunctionType(_top_code(derived, name), namespace, name, original.__defaults__, None)
        view.__kwdefaults__ = original.__kwdefaults__
        view.__annotations__ = dict(original.__annotations__)
        if not inspect.isgeneratorfunction(view) or view.__closure__ is not None:
            raise ValueError('complete city-scene view must be a closure-free generator')
        views[name] = namespace[name] = view
    return namespace, views, originals, artifacts['admissions']


def _forward_scene(session):
    """The caller already owns its LONG; forward only the actual typed waits."""
    current = session.start()
    while type(current) in (GameplaySceneWait, ScriptedSceneWait):
        waiting = current
        returned = yield waiting
        if type(waiting) is GameplaySceneWait and not waiting.needs_interrupt:
            if returned is not waiting.frame:
                raise ValueError('device progress cannot replace the live scene frame')
            current = session.resume_device(waiting.event)
        else:
            current = session.resume_interrupt(returned, waiting.poll)
    return current


class CityScenePrograms(CommandMessagePrograms):
    """Extend only the three actual display pairs; all other routes stay original."""

    def __init__(self, state):
        super().__init__(state)
        from ..high_level_remaining_flows import business_lowbank
        self.lowbank_module = business_lowbank
        namespace, self.city_views, self.city_originals, self.city_admissions = \
            _compile_views(business_lowbank, 'lowbank')
        namespace['_city_scene_lowbank_child'] = self._lowbank_child

    def require_current(self, state):
        super().require_current(state)
        # Base construction calls no child. Once the finite source views exist,
        # retain every exact source owner across all asynchronous continuations.
        if hasattr(self, 'city_originals'):
            for name, original in self.city_originals.items():
                if getattr(self.lowbank_module, name) is not original:
                    raise ValueError('actual city-scene source owner was rebound: ' + name)

    def _lowbank_child(self, state, frame, target, continuation):
        self.require_current(state)
        if target == 0x1072C:
            if (target, continuation) not in SCENE_CALL_PAIRS:
                raise MovementContinuationBoundary(target, frame, 'not an actual city1072C caller LONG')
            return (yield from _forward_scene(GameplaySceneLoadSession(state, frame)))
        return self.city_originals['_lowbank_ui_known_child_fields'](state, frame, target)

    def _display_child(self, state, frame, target, continuation):
        self.require_current(state)
        if target == 0x498:
            if continuation != 0x3CE:
                raise MovementContinuationBoundary(target, frame, 'battle main tail requires actual3CE LONG')
            from ..high_level_gameplay_flow.battle_entry_steps import complete_battle_main_scene_program
            return (yield from complete_battle_main_scene_program(state, frame))
        if target in CITY_ENTRIES:
            if continuation != 0xDFD8:
                raise MovementContinuationBoundary(target, frame, 'city execution requires originalDFD8 LONG')
            return (yield from self.city_views[CITY_ENTRIES[target]](state, frame))
        if target == 0xAF48 and continuation == 0xE022:
            return (yield from _forward_scene(GameplaySceneRefreshSession(state, frame)))
        return (yield from super()._display_child(state, frame, target, continuation))

    def main_scene_call(self, state, frame, target, continuation):
        if target != 0x498:
            return (yield from super().main_scene_call(state, frame, target, continuation))
        self.require_current(state)
        if self._started or continuation != 0x3CE:
            raise ValueError('one actual indexed Main498/3CE call required')
        self._started = True
        return (yield from self.views[('display', 'display_call_fields')](state, frame, target, continuation))


