class PersistentCitySceneSession:
    """Whole00300, with real device/IRQ waits propagated from one entered city.

    This is an explicit additive main owner, not an implicit replacement for
    BootstrapMainSession. Callers must select it before the00300 invocation;
    it cannot attach by rerunning a live main prefix. No incoming return slot
    is fabricated and the original main loop remains nonreturning.
    """

    def __init__(self, state: SceneState, frame: FirstDeploymentFrame):
        self.state = checked_state(state)
        self.entry = _movement_frame(state, frame)
        if frame.status != state.sr & 31:
            raise ValueError('city main entry must retain actual full SR/CCR-X')
        self._thread = threading.get_ident()
        self._program, self._module, self._originals, self.admissions = _make_city_main_program(state, frame)
        self._started = self._failed = False
        self.waiting = None
        self.suspensions = 0
        self.status_word = state.sr

    def _require_current(self):
        if threading.get_ident() != self._thread:
            raise ValueError('city main continuation belongs to another thread')
        for name, original in self._originals.items():
            if getattr(self._module, name) is not original:
                raise ValueError('actual complete main owner was rebound: ' + name)

    def _take(self, returned=None):
        from ..high_level_gameplay_flow.battle_trigger_steps import BattleTriggerWait
        self._require_current()
        try:
            waiting = next(self._program) if returned is None else self._program.send(returned)
        except StopIteration:
            self._failed = True
            raise Boundary('original nonreturning city main completed without an actual continuation')
        except BaseException:
            self._failed = True
            raise
        allowed = (BootstrapMainWait, ControllerSetupWait, ForceTurnWait, GameplaySceneWait, ScriptedSceneWait, AllocationSceneWait, DuelSceneWait, BattleTriggerWait)
        if type(waiting) not in allowed or waiting.state is not self.state:
            self._failed = True
            raise ValueError('an actual same-Scene main/message/load/scripted wait is required')
        self.waiting = waiting.validate()
        self.status_word = self.state.sr
        self.suspensions += 1
        return self.waiting

    def start(self):
        self._require_current()
        if self._started:
            raise ValueError('cannot replay original00300 initialization or city prefixes')
        self._started = True
        return self._take()

    def _live(self):
        self._require_current()
        if not self._started or self._failed or self.waiting is None:
            raise ValueError('one live suspended city main invocation required')

    def resume_interrupt(self, returned: FirstDeploymentFrame, pc: int):
        self._live()
        waiting = self.waiting
        if type(waiting) is GameplaySceneWait and (not waiting.needs_interrupt):
            raise ValueError('this scene point requires an explicit device event, not an IRQ')
        returned = _movement_frame(self.state, returned)
        uint(pc, 32)
        if pc != waiting.poll:
            raise MovementContinuationBoundary(pc, returned, 'IRQ did not RTE to the actual city/main poll')
        if returned.stack_cursor.base != waiting.frame.stack_cursor.base:
            raise Boundary('IRQ must preserve the suspended city physical SP')
        if self.state.sr != self.status_word or returned.status != self.status_word & 31:
            raise ValueError('IRQ must restore the original city full SR and CCR-X')
        return self._take(returned)

    def resume(self, returned: FirstDeploymentFrame, pc: int):
        return self.resume_interrupt(returned, pc)

    def resume_device(self, event: str):
        self._live()
        waiting = self.waiting
        if type(waiting) is not GameplaySceneWait or waiting.needs_interrupt or event != waiting.event:
            raise ValueError('the exact suspended city device event is required')
        if self.state.sr != self.status_word:
            raise ValueError('device progress cannot change the original full software SR')
        return self._take(waiting.frame)
